  _cbU=Math.max(0,_cbP-0.15*(_cbL+1)/4/0.22); _cbV=Math.min(1,_cbU/0.85); _cbS=-_cbA+2*_cbA*_cbV*(2-_cbV);
  if(_cbT-_cbS<0.03||_cbF<=0) continue;
